UPDATE businesses SET description = 'Xolile Guestrooms is a self-catering guest house on Washington Street in Langa, offering visitors a warm, authentic place to stay in one of Cape Town''s oldest townships. It is a popular choice for travellers interested in cultural tourism who want to experience township life first-hand rather than from a city hotel.

The guest house has neat, comfortable ensuite rooms with the essentials needed for a restful stay, and guests share a communal kitchen where they can prepare their own meals. The premises are secure, and the hosts create a friendly, welcoming atmosphere that makes independent travellers and groups feel at home. Its location on one of Langa''s main historical streets puts heritage sites, community art centres and public transport within easy reach, making it a practical base for exploring both Langa and the wider city. Xolile Guestrooms is at 1 Xolile House, Washington Street, Langa.', description_enriched_at = datetime('now') WHERE slug = 'xolile-guestrooms-langa' AND description = 'Xolile Guestrooms is a self-catering guest house in Langa offering ensuite rooms with essential amenities.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
